function isDark() { return document.documentElement.dataset.theme === 'dark' || (document.documentElement.dataset.theme !== 'light' && matchMedia('(prefers-color-scheme: dark)').matches); }   // i18n-ignore
function setAccent(el, ch) {
  const i = ch ? (ch._ci ?? ch._i) % PALETTE.length : 7;
  const c = isDark() ? PALETTE_DARK[i] : PALETTE[i][0];
  const bg = isDark() ? `color-mix(in srgb, ${PALETTE_DARK[i]} 18%, #1f232e)` : PALETTE[i][1];   // i18n-ignore
  el.style.setProperty('--c', c); el.style.setProperty('--c-bg', bg);
}
function applyTheme() {
  const t = S.settings.theme;
  if (t === 'auto') delete document.documentElement.dataset.theme; else document.documentElement.dataset.theme = t;
}

/* ---------- progress ---------- */
function chProgress(c) {
  const sr = c.sections.filter(s => S.read[s.id]).length / c.sections.length;
  const ex = c.exercises.filter(e => solved(e.id)).length / c.exercises.length;
  return { sr, ex };
}

/* ---------- section plain text (for AI context) ---------- */
/* i18n-ignore-start */   // context for the AI's prompts (English, like the prompts themselves)
function blockText(b) {
  switch (b.t) {
    case 'p': return b.text;
    case 'list': return b.items.map(x => '- ' + x).join('\n');
    case 'code': return '```' + (b.lang || '') + '\n' + b.code + '\n```';
    case 'diagram': return b.text;
    case 'table': return [b.head.join(' | '), ...b.rows.map(r => r.join(' | '))].join('\n');
    case 'callout': return `[${b.kind.toUpperCase()}] ${b.title || ''}: ${b.text}`;
    case 'compare': return b.items.map(i => i.title + ': ' + i.points.join('; ')).join('\n');
    case 'flow': return b.items.join(' → ');
    case 'reveal': return `Q: ${b.label}\nA: ${b.text}`;
    case 'ask': return (b.title || 'Ask yourself') + ':\n' + b.questions.map((q, i) => `${i + 1}. ${q}`).join('\n');
    case 'terms': return b.items.map(i => `${i.term}: ${i.def}`).join('\n');
    case 'figure': return figureAsText(b);
    case 'interactive': return interactiveAsText(b);
  }
  return '';
}
function sectionText(s) { return `## ${s.title}\n${s.hook || ''}\n` + s.blocks.map(blockText).join('\n\n'); }
function chapterOutline(c) {
  return `# Chapter ${c.num}: ${c.title} — ${c.subtitle}\nMantra: ${c.mantra}\nSections:\n` + c.sections.map(s => `- ${s.title}: ${s.hook || ''}`).join('\n') +
    '\nKey pitfalls:\n' + c.pitfalls.map(p => `- ${p.title}: ${p.text}`).join('\n');
}
/* i18n-ignore-end */

/* ---- 15_inbox.js ---- */
/* ===================== Results inbox: study results that other apps append (e.g. Meletee) ===================== */
/* A subject's progress is one blob (s:<subject>:state) that the open tab rewrites on every save, so no other app may
   write it. Other apps append rows to noema_kv instead: key a:inbox:<app>:<id>, value (schema noema.results/v1)
     { schema, app, subject, at, items: [{ kind: 'section'|'chapter'|'exercise'|'card', id, event?, ok?, grade?, rating?, date?, at }] }
   The open subject applies its own rows (on start and after each pull), saves, pushes, then deletes them — the same
   pattern as the Claude app's a:curin: answers (engine/curjobs.js). Rows of other subjects wait until that subject is
   opened. Applying is idempotent: the keys of applied rows are kept in the state (S.inboxDone) and saved together with
   what they changed, so a row read twice (a failed delete, two open tabs) counts once. Malformed items are skipped. */
const INBOX = 'a:inbox:', RESULTS_SCHEMA = 'noema.results/v1', INBOX_KEEP = 500, EXT_KEEP = 200;
const inboxRun = { busy: false };
function cardKeyKnown(key) { return FULL_COURSE.some(c => c.flashcards.some(f => f._key === key)); }   // card keys as the decks use them (50_sources.js)
/** Apply one parsed row to S (no saving) → how many items were applied. */
function applyResults(v) {
  let n = 0;
  const app = /^[a-z0-9_-]{1,32}$/i.test(v.app) ? v.app : 'app';
  for (const it of Array.isArray(v.items) ? v.items : []) {
    if (!it || typeof it !== 'object' || typeof it.id !== 'string') continue;
    const at = Date.parse(it.at) || Date.parse(v.at) || Date.now();
    if (it.kind === 'section' && it.event === 'studied' && SEC[it.id]) { S.read[it.id] = true; n++; }
    else if (it.kind === 'exercise' && typeof it.ok === 'boolean' && EX[it.id]) { record(EX[it.id], it.ok); n++; }
    else if (it.kind === 'card' && [0, 1, 2].includes(it.grade) && cardKeyKnown(it.id)) { rateCardKey(it.id, it.grade, new Date(at)); n++; }
    else if ((it.event === 'review' || it.event === 'studied') && (it.kind === 'chapter' ? CH[it.id] : SEC[it.id])) {
      // what noema-lite has no field for (a chapter studied elsewhere, a spaced review and its rating): kept for display
      S.ext = S.ext || {};
      const log = S.ext[app] = Array.isArray(S.ext[app]) ? S.ext[app] : [];
      log.push({ kind: it.kind, id: it.id, event: it.event, rating: typeof it.rating === 'string' ? it.rating.slice(0, 20) : undefined, date: typeof it.date === 'string' ? it.date.slice(0, 10) : undefined, at: new Date(at).toISOString() });
      if (log.length > EXT_KEEP) log.splice(0, log.length - EXT_KEEP);
      n++;
    }
  }
  return n;
}
/** Read the inbox, apply this subject's rows, save + push, then delete them → how many items were applied. */
async function checkInbox() {
  const CL = window.NoemaCloud;
  if (inboxRun.busy || ACCOUNT.kind !== 'cloud' || !CL?.session?.() || !CL.kvRows) return 0;
  inboxRun.busy = true; let n = 0;
  try {
    const rows = (await CL.kvRows(INBOX)).sort((a, b) => a.key.localeCompare(b.key));   // storage keys, not words (i18n-ignore)
    const done = []; const seen = S.inboxDone = S.inboxDone || {};
    for (const r of rows) {
      let v; try { v = JSON.parse(r.value); } catch (e) { done.push(r.key); continue; }   // unreadable: it can never be applied
      if (!v || typeof v !== 'object' || v.schema !== RESULTS_SCHEMA) continue;            // another format (a newer app?): leave it
      if (v.subject !== SUBJ.id) continue;                                                   // another subject: applied when that one is opened
      if (!seen[r.key]) { n += applyResults(v); seen[r.key] = Date.now(); }
      done.push(r.key);
    }
    if (!done.length) return 0;
    const keep = Object.entries(seen).sort((a, b) => b[1] - a[1]).slice(0, INBOX_KEEP); S.inboxDone = Object.fromEntries(keep);
    flushSave();
    // the changed state reaches the cloud BEFORE its rows leave the inbox (a failed push keeps them for the next check)
    if (n) await CL.push(ACCOUNT.id);
    for (const k of done) await CL.kvDelete(k).catch(() => { });
    if (n) { toast('📥 ' + tE('engine.inbox.applied', { n })); renderTopStats(); }
  } catch (e) { console.warn('[inbox]', e); } finally { inboxRun.busy = false; }
  return n;
}
addEventListener('noema:pulled', e => { if (e.detail?.acc === ACCOUNT.id) checkInbox(); });
setTimeout(checkInbox, 0);   // once the whole engine has loaded
{ /* tell sibling apps (Meletee, a:caps) that results can be appended here; each feature merges only its own flag */
  const k = Noema.kv.accountKey('caps'); let c = {}; try { c = JSON.parse(Noema.kv.get(k) || '{}') || {}; } catch (e) { }
  if (!c.resultsInbox) Noema.kv.set(k, JSON.stringify({ ...c, resultsInbox: 1 }));
}

/* ---- 20_ai.js ---- */
/* ===================== Gemini client ===================== */
const GEM_BASE = 'https://generativelanguage.googleapis.com/v1beta';
/** An error of the Gemini client in the learner's words (needsKey: the 🔑 guide helps). */
const gemErr = (key, vars, extra) => Object.assign(new Error(tE(key, vars)), extra || {});
/** Gemini could not be reached (docs/i18n.md §6): the English words in .message (logs), the code for the learner's words (errText → err.ai.network_gemini). */
const gemNetErr = e => Object.assign(new Error(`Network error — are you online? (${e && e.message})`), { code: 'ai.network_gemini', params: { detail: String(e && e.message) } });   // i18n-ignore (English .message of the error contract)
const FALLBACK_MODELS = ['gemini-flash-latest', 'gemini-2.5-flash', 'gemini-2.0-flash'];

function modelScore(name) {
  const n = name.replace(/^models\//, '');
  if (/(image|tts|audio|live|embed|aqa|gemma|robotics|computer|native|veo|imagen|learnlm|nano|banana|thinking-exp|research|deep)/i.test(n)) return -1;
  if (!/gemini/i.test(n)) return -1;
  let s = 0;
  const v = n.match(/gemini-(\d+(?:\.\d+)?)/);
  if (v) s += parseFloat(v[1]) * 100; else if (/latest/.test(n)) s += 240;
  if (/flash/.test(n)) s += 60;
  if (/lite/.test(n)) s -= 45;
  if (/pro/.test(n)) s += 20;
  if (/preview|exp/.test(n)) s -= 8;
  if (/\d{2}-\d{2}|\d{3}$/.test(n)) s -= 3;
  return s;
}
async function detectModels() {
  const key = S.settings.apiKey;
  if (!key) throw gemErr('engine.gemini.noKeySet', null, { needsKey: true });
  let r; try { r = await fetch(`${GEM_BASE}/models?pageSize=1000`, { headers: { 'x-goog-api-key': key } }); } catch (e) { throw gemNetErr(e); }   // offline: the coded network error (docs/i18n.md §6)
  if (!r.ok) throw gemErr('engine.gemini.modelListFailed', { status: r.status, detail: (await r.text()).slice(0, 200) });
  const d = await r.json();
  const ms = (d.models || []).filter(m => (m.supportedGenerationMethods || []).includes('generateContent'))
    .map(m => m.name.replace(/^models\//, '')).filter(n => modelScore(n) >= 0)
    .sort((a, b) => modelScore(b) - modelScore(a));
  S.settings.models = ms;
  if (!S.settings.model || !ms.includes(S.settings.model)) S.settings.model = ms[0] || FALLBACK_MODELS[0];
  save();
  return ms;
}
async function ensureModel() {
  if (S.settings.model) return S.settings.model;
  try { await detectModels(); } catch (e) { S.settings.model = FALLBACK_MODELS[0]; }
  return S.settings.model;
}
function thinkingFor(model) {
  if (/gemini-3/.test(model)) return { thinkingLevel: 'low' };
  if (/2\.5-flash/.test(model)) return { thinkingBudget: 0 };
  if (/2\.5-pro/.test(model)) return { thinkingBudget: 128 };
  return null;
}
const noThinking = new Set();
function buildBody({ system, contents, json, schema, temperature = 0.7, model }) {
  const gc = { temperature };
  if (json) { gc.responseMimeType = 'application/json'; if (schema) gc.responseSchema = schema; }
  const th = noThinking.has(model) ? null : thinkingFor(model);
  if (th) gc.thinkingConfig = th;
  const body = { contents, generationConfig: gc };
  if (system) body.systemInstruction = { parts: [{ text: system }] };
  return body;
}
function friendlyError(status, text) {
  if (status === 400 && /API key/i.test(text)) return tE('engine.gemini.keyRejected');   // i18n-ignore (a pattern of Gemini's answer)
  if (status === 403) return tE('engine.gemini.denied');
  if (status === 404) return tE('engine.gemini.noModel');
  if (status === 429) return tE('engine.gemini.rateLimit');
  if (status >= 500) return tE('engine.gemini.hiccup', { status });
  return tE('engine.gemini.error', { status, detail: text.slice(0, 220) });
}
async function gemini(opts, retry = 1) {
  const model = await ensureModel();
  const key = S.settings.apiKey;
  if (!key) throw gemErr('engine.gemini.noKey', null, { needsKey: true });
  const stream = !!opts.onChunk;
  const url = `${GEM_BASE}/models/${model}:${stream ? 'streamGenerateContent?alt=sse' : 'generateContent'}`;   // i18n-ignore
  let r;
  try {
    r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key }, body: JSON.stringify(buildBody({ ...opts, model })) });
  } catch (e) { throw gemNetErr(e); }
  if (!r.ok) {
    const t = await r.text();
    if (r.status === 400 && /thinking/i.test(t) && !noThinking.has(model)) { noThinking.add(model); return gemini(opts, retry); }
    if (r.status === 404 && retry > 0) {
      const alt = FALLBACK_MODELS.find(m => m !== model);
      try { await detectModels(); } catch (e) { S.settings.model = alt; }
      if (S.settings.model !== model) return gemini(opts, retry - 1);
    }
    if ((r.status === 503 || r.status === 500) && retry > 0) { await sleep(1200); return gemini(opts, retry - 1); }
    throw Object.assign(new Error(friendlyError(r.status, t)), r.status === 400 && /API key/i.test(t) ? { needsKey: true } : {});   // i18n-ignore
  }
  const partsText = d => (d.candidates?.[0]?.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('');
  if (!stream) {
    const d = await r.json();
    const txt = partsText(d);
    if (!txt) throw d.promptFeedback?.blockReason ? gemErr('engine.gemini.emptyBlocked', { reason: d.promptFeedback.blockReason }) : gemErr('engine.gemini.empty');
    return txt;
  }
  const reader = r.body.getReader(), dec = new TextDecoder();
  let buf = '', full = '';
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
      if (!line.startsWith('data:')) continue;
      try { const d = JSON.parse(line.slice(5)); const t = partsText(d); if (t) { full += t; opts.onChunk(full); } } catch (e) { }
    }
  }
  if (!full) throw gemErr('engine.gemini.empty');
  return full;
}
async function geminiJSON(prompt, system, schema) {
  const txt = await gemini({ system, contents: [{ role: 'user', parts: [{ text: prompt }] }], json: true, schema, temperature: 0.4 });
  const m = txt.match(/\{[\s\S]*\}/);
  return JSON.parse(m ? m[0] : txt);
}

/* ===================== Tutor ===================== */
