      if (f.media && typeof MEDIA !== 'undefined' && MEDIA[f.media]) box.append(figureBlock({ t: 'figure', media: f.media, explore: false }));
      if (f.text) box.append(h('p', { class: 'act-fbtext', html: fmt(f.text) }));
