  if (ex.grid && m) { const [c, rr] = ex.grid; tiles = []; for (let j = 0; j < rr; j++) for (let i = 0; i < c; i++) tiles.push({ id: `t${j * c + i}`, shape: 'rect', x: i * m.w / c, y: j * m.h / rr, w: m.w / c, h: m.h / rr, rx: 0 }); }
