  const idle = () => { clock?.classList.remove('running'); if (clock) { if (clock.classList.contains('ns-focus')) clock.remove(); else clock.textContent = '⏱️ ' + t('top.focus'); } };
  if (timerT) { clearInterval(timerT); timerT = null; idle(); return; }
