/* ---------- open a stored conversation ---------- */
function findFull(kind, id) {
  for (const c of FULL_COURSE) {
    if (kind === 'chapter' && c.id === id) return c;
    if (kind === 'section' && c.sections.some(s => s.id === id)) return c;
    if (kind === 'playbook' && c.debug.some(d => d.id === id)) return c;
    if (kind === 'exercise') { const e = c.exercises.find(x => x.id === id); if (e) return e; }
  }
  return null;
}
function openConvo(cv) {
  let ctx = null;
  const r = cv.ctx;
  if (r) {
    const visible = r.kind === 'section' ? SEC[r.id] : r.kind === 'chapter' ? CH[r.id] : r.kind === 'playbook' ? PB[r.id] : r.kind === 'exercise' ? findFull('exercise', r.id) : null;
    if (!visible && findFull(r.kind, r.id)) { setSrcFilter(null); }   // its source is filtered out → show everything again
    if (r.kind === 'exercise') { const e = findFull('exercise', r.id); ctx = e ? { kind: 'exercise', id: r.id, text: exerciseAsText(e) } : null; }
    else ctx = { kind: r.kind, id: r.id, label: r.label, ...(r.kind === 'item' ? { sec: r.sec || null, ch: r.ch || null, text: r.text || r.label } : {}) };
  }
  T.ctx = ctx; T.mode = MODES[cv.mode] ? cv.mode : (cv.kind && cv.kind !== 'tutor') || cv.mode ? 'explain' : 'socratic';   // another app's mode (e.g. Meletee's feynman) continues as a plain explanation; the record keeps its mode
  const key = tutorCtxKey();
  T.hist[key] = cv.msgs; CV.byKey[key] = cv;
  if (cv.tutorState) T.tstate[key] = cv.tutorState; else if (T.mode === 'socratic' && cv.msgs.some(m => m.meta?.noemaState)) T.tstate[key] = cv.tutorState = rebuildThreadState(cv.msgs); else delete T.tstate[key];
  T.showHistory = false; renderTutor();
}

/** The frame's conversations window asked to continue one of this subject's conversations (engine/shell.js goConvo). */
function resumeConvo() {
  let f = null; try { f = JSON.parse(sessionStorage.getItem('noema-device:openConvo') || 'null'); sessionStorage.removeItem('noema-device:openConvo'); } catch (e) { }
  if (!f || f.acc !== ACCOUNT.id || f.sid !== SUBJ.id) return;
  const cv = CV.list.find(c => c.id === f.id); if (!cv) return;
  openTutor(); openConvo(cv);
}
/** A conversation renamed or deleted in the frame's window: keep this subject's copy in step. */
function convoChanged(id, patch) {
  const cv = CV.list.find(c => c.id === id); if (!cv) return;
  if (patch) { Object.assign(cv, patch); if (patch.title) { cv.titleSource = 'user'; cv.titledLen = 1e9; } }
  else { CV.list = CV.list.filter(x => x !== cv); for (const k in CV.byKey) if (CV.byKey[k] === cv) { delete CV.byKey[k]; delete T.hist[k]; } }
  if (T.open) renderTutor();
}

